html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro lines(value, blank=3) -%}
{%- if value %}<p class="answer">{{ v(value) | replace("\n", "<br>") }}</p>{% else %}{% for i in range(blank) %}<p class="dots"></p>{% endfor %}{% endif -%}
{%- endmacro -%}
{%- macro person(user) -%}{{ v(frappe.db.get_value("User", user, "full_name") if user else "") }}{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}
{%- set objectives = (doc.objectives or []) + [{}] * (8 - (doc.objectives or []) | length) -%}
{%- set needs = (doc.training_needs or []) + [{}] * (7 - (doc.training_needs or []) | length) -%}
{%- set next_objectives = (doc.next_objectives or []) + [{}] * (7 - (doc.next_objectives or []) | length) -%}
{%- macro signature(label, remarks, user, on) -%}
	<h4>{{ label }}</h4>
	{{ lines(remarks, 2) }}
	<table class="plain"><tr>
		<td style="width: 34%">Name: {{ person(user) or "................................" }}</td>
		<td style="width: 33%">Designation: {{ v(frappe.db.get_value("Employee", {"user_id": user}, "designation") if user else "") or "..........................." }}</td>
		<td>Date: {{ day(on) or "......................" }}</td>
	</tr></table>
{%- endmacro -%}
<style>
	.lpl { font-family: Arial, Helvetica, sans-serif; font-size: 10.5px; color: #000; }
	.lpl table { width: 100%; border-collapse: collapse; margin: 0 0 8px; }
	.lpl tr { page-break-inside: avoid; }
	.lpl td, .lpl th { border: 1px solid #555; padding: 4px 6px; vertical-align: top; text-align: left; }
	.lpl th, .lpl td.lbl { background: #f2f2f2; font-weight: bold; }
	.lpl td.val { height: 18px; }
	.lpl .head td { vertical-align: middle; font-weight: bold; }
	.lpl .head .title { text-align: center; }
	.lpl .no { width: 26px; background: #f2f2f2; font-weight: bold; }
	.lpl .num { width: 13%; text-align: center; }
	.lpl h4 { font-size: 11.5px; font-weight: bold; text-decoration: underline; margin: 12px 0 4px; }
	.lpl p { margin: 0 0 4px; }
	.lpl .q { font-weight: bold; margin: 10px 0 3px; }
	.lpl .answer { border-bottom: 1px dotted #777; padding: 0 0 3px; }
	.lpl .dots { border-bottom: 1px dotted #777; height: 16px; margin: 0; }
	.lpl table.plain td { border: none; padding: 10px 0 0; }
	.lpl .ref { text-align: right; font-size: 9.5px; }
	.lpl .box { display: inline-block; width: 12px; height: 12px; border: 1px solid #000; margin-right: 6px; text-align: center; line-height: 11px; }
</style>
<div class="lpl">
	<table class="head">
		<tr>
			<td rowspan="3" style="width: 18%; text-align: center">{% if logo %}<img src="{{ logo }}" style="max-width: 100%; max-height: 56px">{% endif %}</td>
			<td rowspan="3" class="title" style="width: 48%">LUUKA PLASTICS LIMITED</td>
			<td class="lbl" style="width: 18%">Doc Ref. No:</td><td>LPL/HR/32</td>
		</tr>
		<tr><td class="lbl">Initial Issue Date</td><td>20/10/2017</td></tr>
		<tr><td class="lbl">Revision Date:</td><td>22/11/2020</td></tr>
		<tr><td colspan="2" class="title">End of probation evaluation/confirmation form</td><td class="lbl">Revision No.</td><td>1</td></tr>
	</table>
	<table>
		<tr>
			<td style="width: 34%"><strong>Name</strong> {{ v(doc.employee_name) }}</td>
			<td style="width: 33%"><strong>Job Title</strong> {{ v(doc.designation) }}</td>
			<td><strong>Date of joining</strong> {{ day(doc.date_of_joining) }}</td>
		</tr>
		<tr>
			<td><strong>Supervisor</strong> {{ v(frappe.db.get_value("Employee", doc.supervisor, "employee_name") if doc.supervisor else "") }}</td>
			<td><strong>Section:</strong> {{ v(doc.department) }}</td>
			<td><strong>End of probation date</strong> {{ day(doc.end_of_probation) }}</td>
		</tr>
	</table>
	<p class="q">Objectives</p>
	<p>The purpose of this appraisal exercise is to measure the employee's performance and contribution during the probation period and to decide on the employee's job confirmation, probation extension or otherwise.</p>
	<p class="q">Guidelines</p>
	<p>The employee should first conduct the self-assessment and after that meet and discuss with the supervisor on the final score with justifications/examples where required. The employee/supervisor should also set the objectives for the next performance period.</p>
	<p>The employees/supervisor should write N/A (Not Applicable) on factors that are not in line with the employee's nature/scope of work.</p>
	<p><strong>Rating Scale: Excellent=5 (90-100%), Very Good=4 (75 to 89%), Good=3 (60 to 74%), Average=2 (50 to 59%), Below average=1 (40% and below)</strong></p>

	<h4>Section A: Ratable Factors</h4>
	<table>
		<tr><th>Factor</th><th class="num">Employee's rating</th><th class="num">Supervisor's rating</th><th style="width: 30%">Supervisor's Comment</th></tr>
		{%- for row in doc.factors or [] %}
		<tr><td>{{ v(row.factor) }}</td><td class="num">{{ v(row.employee_rating) }}</td><td class="num">{{ v(row.supervisor_rating) }}</td><td>{{ v(row.supervisor_comment) }}</td></tr>
		{%- endfor %}
	</table>

	<h4>Section B: Performance objectives / Key Performance Indicators (KPIs) during probation</h4>
	<p>(Objectives / KPIs should be in line with the departmental / section objectives / KPIs)</p>
	<table>
		<tr><th class="no">No.</th><th>Objectives / KPIs for probation period</th><th class="num">Employee's Rating</th><th class="num">Supervisor's Rating</th><th style="width: 26%">Comments by the Supervisor</th></tr>
		{%- for row in objectives %}
		<tr><td class="no">{{ loop.index }}.</td><td class="val">{{ v(row.objective) }}</td><td class="num">{{ v(row.employee_rating) }}</td><td class="num">{{ v(row.supervisor_rating) }}</td><td>{{ v(row.comments) }}</td></tr>
		{%- endfor %}
	</table>

	<h4>SECTION C: OVERALL SCORES/RATING</h4>
	<p>Overall rating; Excellent=90-100%, Very Good=75-89%, Good=60-74%, Average=50-59%, Below Average=49% and below</p>
	<table style="width: 55%; margin-left: auto">
		<tr><td></td><th class="num">Total Rating</th></tr>
		<tr><td class="lbl">Ratable Factors</td><td class="num">{{ v(doc.factors_score) }} /60</td></tr>
		<tr><td class="lbl">Objectives/KPIs</td><td class="num">{{ v(doc.objectives_score) }} /40</td></tr>
		<tr><td class="lbl">Total Score</td><td class="num">{{ v(doc.total_score) }} %</td></tr>
		<tr><td class="lbl">Overall Rating</td><td class="num">{{ v(doc.rating_band) }}</td></tr>
		<tr><td class="lbl">Pass Mark</td><td class="num">{{ v(doc.pass_mark) }} %{% if doc.total_score is not none %}: {{ "Passed" if doc.passed else "Not passed" }}{% endif %}</td></tr>
	</table>

	<h4>SECTION D: Achievements, challenges and training needs</h4>
	<p class="q">A. What were your achievements during the period under review?</p>
	{{ lines(doc.achievements, 6) }}
	<p class="q">B. What performance challenges/problems did you face and how can they be resolved?</p>
	{{ lines(doc.challenges, 4) }}
	<p class="q">C. Training and Development needs/skills</p>
	<table>
		<tr><th>Trainings/skills to be developed</th><th>How to develop the skill</th><th>Measurement criteria</th></tr>
		{%- for row in needs %}
		<tr><td class="val">{{ v(row.skill) }}</td><td>{{ v(row.how_to_develop) }}</td><td>{{ v(row.measurement) }}</td></tr>
		{%- endfor %}
	</table>

	<h4>SECTION E: Objectives / KPIs for the next performance period (i.e from {{ day(doc.next_period_from) or "......................" }} to {{ day(doc.next_period_to) or "......................" }})</h4>
	<table>
		<tr><th class="no">No.</th><th>Objectives / KPIs</th><th style="width: 40%">Measurement criteria</th></tr>
		{%- for row in next_objectives %}
		<tr><td class="no">{{ loop.index }}</td><td class="val">{{ v(row.objective) }}</td><td>{{ v(row.measurement) }}</td></tr>
		{%- endfor %}
	</table>

	<h4>SECTION F: Recommendations/signatures</h4>
	<p class="q">Employee's remarks/comments</p>
	{{ lines(doc.employee_remarks, 2) }}
	<table class="plain"><tr>
		<td style="width: 34%">Name: {{ v(doc.employee_name) }}</td>
		<td style="width: 33%">Designation: {{ v(doc.designation) }}</td>
		<td>Date: {{ day(doc.employee_signed_on) or "......................" }}</td>
	</tr></table>
	{{ signature("Immediate Supervisor's remarks/comments", doc.supervisor_remarks, doc.supervisor_by, doc.supervisor_on) }}
	{%- if doc.position_category != "Administrative" %}
	{{ signature("Manager's remarks/comments", doc.manager_remarks, doc.manager_by, doc.manager_on) }}
	{%- endif %}
	{{ signature("Head of Department's remarks/comments", doc.hod_remarks, doc.hod_by, doc.hod_on) }}
	<h4>Human Resources Manager's recommendation</h4>
	<p><strong>{{ v(doc.hrm_recommendation) }}</strong></p>
	{{ lines(doc.hrm_remarks, 2) }}
	<table class="plain"><tr>
		<td style="width: 34%">Name: {{ person(doc.hrm_by) or "................................" }}</td>
		<td style="width: 33%">Designation: Human Resources Manager</td>
		<td>Date: {{ day(doc.hrm_on) or "......................" }}</td>
	</tr></table>
	{%- if doc.ed_decision %}
	<h4>Executive Director's decision</h4>
	<p><strong>{{ v(doc.ed_decision) }}</strong>{% if doc.ed_decision == "Confirm" and doc.confirmation_date %}, from {{ day(doc.confirmation_date) }}{% elif doc.ed_decision == "Extend Probation" and doc.new_end_of_probation %}, to {{ day(doc.new_end_of_probation) }}{% endif %}</p>
	{{ lines(doc.ed_remarks, 1) }}
	<table class="plain"><tr>
		<td style="width: 34%">Name: {{ person(doc.ed_by) }}</td><td style="width: 33%">Designation: Executive Director</td><td>Date: {{ day(doc.ed_on) }}</td>
	</tr></table>
	{%- endif %}
</div>
